'-- (CALLING_PARAMETERS.LICE_NO.WHEN-VALIDATE-ITEM: port NVL(P_PORT_CD, PARAMETER.P_CURR_PORT_CD), message if not found)',
'SELECT l.seq, l.p_agr_nbr,',
