'       CONNECT BY REGEXP_SUBSTR(REGEXP_REPLACE(:P2210_LICE_NO, ''\s'', ''''), ''[^,]+'', 1, LEVEL) IS NOT NULL) l,',
'       importers i',
' WHERE i.impr_nbr (+) = l.p_agr_nbr',
'   AND i.port_cd (+) = NVL(:P2210_P_PORT_CD, :P_CURR_PORT_CD)',
' ORDER BY l.seq'))
